<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Solar Assistant</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.1.1/css/all.min.css"><link rel="stylesheet" href="css/style.css"><style>.assistant-shell{max-width:1000px;margin:0 auto;padding:7rem 3rem}.assistant-heading{max-width:70rem;margin-bottom:2rem}.assistant-heading h1{font-family:'Barlow Condensed',sans-serif;font-size:6rem;line-height:.95}.assistant-heading em{color:var(--accent);font-style:normal}.assistant-note{color:var(--light-color);font-size:1.4rem;line-height:1.6}.assistant-card{background:var(--white);border:var(--border);padding:2rem}.assistant-log{min-height:30rem;max-height:55rem;overflow:auto;display:grid;gap:1rem;margin-bottom:1.5rem}.assistant-message{max-width:85%;padding:1.2rem 1.4rem;border:var(--border);font-size:1.35rem;line-height:1.6}.assistant-message.bot{background:var(--light-bg)}.assistant-message.user{justify-self:end;background:var(--accent);color:#151713}.assistant-form{display:flex;gap:.8rem}.assistant-form input{flex:1;padding:1.2rem;background:var(--light-bg);border:var(--border);font-size:1.4rem}.assistant-product{display:flex;gap:1rem;align-items:center;margin-top:1rem;padding-top:1rem;border-top:var(--border)}.assistant-product img{width:7rem;height:5rem;object-fit:contain}.assistant-product small{display:block;color:var(--light-color)}@media(max-width:600px){.assistant-shell{padding:4rem 1.5rem}.assistant-heading h1{font-size:4.5rem}.assistant-form{flex-direction:column}.assistant-message{max-width:100%}}</style></head><body><?php include 'components/user_header.php'; ?><main class="assistant-shell"><header class="assistant-heading"><p class="section-kicker">SOLAR SUPPORT / AI ASSISTANT</p><h1>Ask about <em>any solar system.</em></h1><p class="assistant-note">Brand, inverter type, battery, panel strings, settings aur error code ke bare mein query karein. Safety-critical changes ke liye exact model aur official manual zaroor verify karein.</p></header><section class="assistant-card"><div id="assistantLog" class="assistant-log"><div class="assistant-message bot">Assalam-o-alaikum! Brand/model, system voltage, battery ya error code likhein. Main verified catalog aur troubleshooting guidance se related answer dunga.</div></div><form id="assistantForm" class="assistant-form"><input id="assistantQuery" type="text" maxlength="500" placeholder="Example: GoodWe battery compatibility ya Solis error settings" value="<?= htmlspecialchars($initial_query,ENT_QUOTES,'UTF-8'); ?>" required><button class="btn" type="submit"><i class="fas fa-paper-plane"></i> Ask</button></form></section></main><?php include 'components/footer.php'; ?><script src="js/script.js"></script><script>
const log=document.getElementById('assistantLog'),form=document.getElementById('assistantForm'),input=document.getElementById('assistantQuery');
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function addMessage(text,kind,products=[]){const el=document.createElement('div');el.className='assistant-message '+kind;el.innerHTML='<div>'+esc(text)+'</div>'+products.map(p=>`<a class="assistant-product" href="solar_product.php?product=${encodeURIComponent((p.company||'')+'|'+(p.model||''))}"><img src="${esc(p.image_url||'images/category-inverter.jpg')}" alt=""><span><strong>${esc(p.company||'')} · ${esc(p.name||'')}</strong><small>${esc(p.model||'')} · ${esc(p.details||'')}</small></span></a>`).join('');log.appendChild(el);log.scrollTop=log.scrollHeight;}
async function ask(q){addMessage(q,'user');input.value='';try{const body=new URLSearchParams({query:q});const response=await fetch('api/solar_assistant.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});const data=await response.json();addMessage(data.answer||'No answer returned.','bot',data.products||[]);}catch(error){addMessage('Assistant service unavailable. Exact model aur error details save kar ke technician/manufacturer support se verify karein.','bot');}}
form.addEventListener('submit',e=>{e.preventDefault();if(input.value.trim())ask(input.value.trim());});
if(input.value.trim())ask(input.value.trim());
</script></body></html>
